-- CarRental Database Schema\nCREATE DATABASE IF NOT EXISTS customerDB;\nUSE customerDB;\n\n-- Users Table\nCREATE TABLE users (\n    user_id INT PRIMARY KEY AUTO_INCREMENT,\n    full_name VARCHAR(255) NOT NULL,\n    email VARCHAR(255) UNIQUE NOT NULL,\n    phone VARCHAR(20) NOT NULL,\n    password_hash VARCHAR(255) NOT NULL,\n    address VARCHAR(255),\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP\n);\n\n-- Cars Table\nCREATE TABLE cars (\n    car_id INT PRIMARY KEY AUTO_INCREMENT,\n    car_name VARCHAR(255) NOT NULL,\n    car_model VARCHAR(100),\n    license_plate VARCHAR(50) UNIQUE NOT NULL,\n    daily_rate DECIMAL(10, 2) NOT NULL,\n    availability_status ENUM('available', 'rented', 'maintenance') DEFAULT 'available',\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Bookings Table\nCREATE TABLE bookings (\n    booking_id INT PRIMARY KEY AUTO_INCREMENT,\n    user_id INT NOT NULL,\n    car_id INT NOT NULL,\n    pickup_date DATE NOT NULL,\n    return_date DATE NOT NULL,\n    total_cost DECIMAL(10, 2) NOT NULL,\n    booking_status ENUM('pending', 'confirmed', 'completed', 'cancelled') DEFAULT 'pending',\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (user_id) REFERENCES users(user_id),\n    FOREIGN KEY (car_id) REFERENCES cars(car_id)\n);\n\n-- Payment Methods Table\nCREATE TABLE payment_methods (\n    payment_method_id INT PRIMARY KEY AUTO_INCREMENT,\n    method_name VARCHAR(100) NOT NULL UNIQUE,\n    method_type ENUM('mobile_wallet', 'mobile_banking', 'international') NOT NULL,\n    is_active BOOLEAN DEFAULT TRUE,\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Payments Table\nCREATE TABLE payments (\n    payment_id INT PRIMARY KEY AUTO_INCREMENT,\n    booking_id INT NOT NULL,\n    payment_method_id INT NOT NULL,\n    amount DECIMAL(10, 2) NOT NULL,\n    payment_status ENUM('pending', 'success', 'failed', 'refunded') DEFAULT 'pending',\n    transaction_reference VARCHAR(255) UNIQUE,\n    payment_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (booking_id) REFERENCES bookings(booking_id),\n    FOREIGN KEY (payment_method_id) REFERENCES payment_methods(payment_method_id)\n);\n\n-- Transactions Table\nCREATE TABLE transactions (\n    transaction_id INT PRIMARY KEY AUTO_INCREMENT,\n    payment_id INT NOT NULL,\n    user_id INT NOT NULL,\n    amount DECIMAL(10, 2) NOT NULL,\n    transaction_type ENUM('payment', 'refund') DEFAULT 'payment',\n    transaction_status ENUM('pending', 'success', 'failed') DEFAULT 'pending',\n    gateway_response LONGTEXT,\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (payment_id) REFERENCES payments(payment_id),\n    FOREIGN KEY (user_id) REFERENCES users(user_id)\n);\n\n-- Insert Payment Methods\nINSERT INTO payment_methods (method_name, method_type, is_active) VALUES\n('eSewa', 'mobile_wallet', TRUE),\n('Fonepay', 'mobile_banking', TRUE),\n('PayPal', 'international', TRUE);\n\n-- Create Indexes for better query performance\nCREATE INDEX idx_user_email ON users(email);\nCREATE INDEX idx_booking_user ON bookings(user_id);\nCREATE INDEX idx_booking_status ON bookings(booking_status);\nCREATE INDEX idx_payment_booking ON payments(booking_id);\nCREATE INDEX idx_transaction_payment ON transactions(payment_id);\nCREATE INDEX idx_transaction_user ON transactions(user_id);\n